import React, { useEffect, useState } from "react";
import MaterialTable from "material-table";
import axios from "axios";
import { url as baseUrl } from "./../../../api";
import { token as token } from "./../../../api";
import { forwardRef } from "react";
import "semantic-ui-css/semantic.min.css";
import "react-widgets/dist/css/react-widgets.css";
import { toast } from "react-toastify";

import AddBox from "@material-ui/icons/AddBox";
import ArrowUpward from "@material-ui/icons/ArrowUpward";
import Check from "@material-ui/icons/Check";
import ChevronLeft from "@material-ui/icons/ChevronLeft";
import ChevronRight from "@material-ui/icons/ChevronRight";
import Clear from "@material-ui/icons/Clear";
import DeleteOutline from "@material-ui/icons/DeleteOutline";
import Edit from "@material-ui/icons/Edit";
import FilterList from "@material-ui/icons/FilterList";
import FirstPage from "@material-ui/icons/FirstPage";
import LastPage from "@material-ui/icons/LastPage";
import Remove from "@material-ui/icons/Remove";
import SaveAlt from "@material-ui/icons/SaveAlt";
import Search from "@material-ui/icons/Search";
import ViewColumn from "@material-ui/icons/ViewColumn";
import "react-toastify/dist/ReactToastify.css";
import "react-widgets/dist/css/react-widgets.css";
//import { makeStyles } from '@material-ui/core/styles'
import { useHistory } from "react-router-dom";
//import {Menu,MenuList,MenuButton,MenuItem,} from "@reach/menu-button";
import "@reach/menu-button/styles.css";
import { Modal, Dropdown } from "react-bootstrap";
import { Button, Menu, Icon } from "semantic-ui-react";

const tableIcons = {
  Add: forwardRef((props, ref) => <AddBox {...props} ref={ref} />),
  Check: forwardRef((props, ref) => <Check {...props} ref={ref} />),
  Clear: forwardRef((props, ref) => <Clear {...props} ref={ref} />),
  Delete: forwardRef((props, ref) => <DeleteOutline {...props} ref={ref} />),
  DetailPanel: forwardRef((props, ref) => (
    <ChevronRight {...props} ref={ref} />
  )),
  Edit: forwardRef((props, ref) => <Edit {...props} ref={ref} />),
  Export: forwardRef((props, ref) => <SaveAlt {...props} ref={ref} />),
  Filter: forwardRef((props, ref) => <FilterList {...props} ref={ref} />),
  FirstPage: forwardRef((props, ref) => <FirstPage {...props} ref={ref} />),
  LastPage: forwardRef((props, ref) => <LastPage {...props} ref={ref} />),
  NextPage: forwardRef((props, ref) => <ChevronRight {...props} ref={ref} />),
  PreviousPage: forwardRef((props, ref) => (
    <ChevronLeft {...props} ref={ref} />
  )),
  ResetSearch: forwardRef((props, ref) => <Clear {...props} ref={ref} />),
  Search: forwardRef((props, ref) => <Search {...props} ref={ref} />),
  SortArrow: forwardRef((props, ref) => <ArrowUpward {...props} ref={ref} />),
  ThirdStateCheck: forwardRef((props, ref) => <Remove {...props} ref={ref} />),
  ViewColumn: forwardRef((props, ref) => <ViewColumn {...props} ref={ref} />),
};

const PatientnHistory = (props) => {
  const [recentActivities, setRecentActivities] = useState([]);
  const [loading, setLoading] = useState(true);
  let history = useHistory();
  const [open, setOpen] = React.useState(false);
  const [saving, setSaving] = useState(false);
  const [record, setRecord] = useState(null);
  const toggle = () => setOpen(!open);
  let notToBeUpdated = ["pmtct_infant_information"];

  // Map activity names for display
  const displayActivityName = (name, data) => {
    if (!name) return name;
    if (name.toLowerCase() === "pmtct enrollment") return "Mother Information- MIP1";
    // For HTS records, check testingType from payload first, then fall back to activityName
    if (name.toLowerCase() === "pmtct hts" || name.toLowerCase() === "retesting" || name.toLowerCase() === "initial") {
      if (data?.testingType && data.testingType.toUpperCase() === "RETESTING") return "Retesting";
      if (name.toLowerCase() === "retesting") return "Retesting";
      return "PMTCT HTS";
    }
    return name;
  };

  // Get pmtctCycleUuid from props
  const pmtctCycleUuid = props.selectedCycleId || props.latestPmtctCycle?.uuid;

  useEffect(() => {
    PatientHistory();
  }, [props.patientObj.id, pmtctCycleUuid]);
  ///GET LIST OF Patients
  const PatientHistory = () => {
    setLoading(true);

    // if (props.patientObj.ancNo) {
    //   axios
    //     .get(`${baseUrl}pmtct/anc/activities/${props.patientObj.ancNo}`, {
    //       headers: { Authorization: `Bearer ${token}` },
    //     })
    //     .then((response) => {

    //       setRecentActivities(response.data);
    //     })

    //     .catch((error) => {
    //     });
    // } else {

      let patientUuid=props.patientObj.patient_uuid
            ? props.patientObj.patient_uuid
            : props.patientObj.patientUuid
            ? props.patientObj.patientUuid
            : props.patientObj.uuid
      // ${patientUuid}?pmtctCycleUuid=${pmtctCycleUuid}
    axios
      .get(
        `${baseUrl}pmtct/anc/getAllActivities/${patientUuid}?pmtctCycleUuid=${pmtctCycleUuid}`,
        {
          headers: { Authorization: `Bearer ${token}` },
        }
      )
      .then((response) => {
        setLoading(false);
        const activities = response.data || [];
        // For HTS activities missing testingType, fetch the record detail
        const htsActivities = activities.filter(
          (a) => a.path === "pmtct-hts" && !a.testingType && a.recordId
        );
        if (htsActivities.length > 0) {
          Promise.all(
            htsActivities.map((a) =>
              axios
                .get(`${baseUrl}pmtct/anc/view-pmtct-hts-enrollment/${a.recordId}`, {
                  headers: { Authorization: `Bearer ${token}` },
                })
                .then((res) => ({ recordId: a.recordId, testingType: res.data?.testingType || "" }))
                .catch(() => ({ recordId: a.recordId, testingType: "" }))
            )
          ).then((results) => {
            const typeMap = {};
            results.forEach((r) => { typeMap[r.recordId] = r.testingType; });
            const enriched = activities.map((a) =>
              a.path === "pmtct-hts" && typeMap[a.recordId]
                ? { ...a, testingType: typeMap[a.recordId] }
                : a
            );
            setRecentActivities(enriched);
          });
        } else {
          setRecentActivities(activities);
        }
      })

      .catch((error) => {
        //console.log(error);
      });
    // }
  };

  const LoadViewPage = (row, action) => {
    if (row.path === "anc-enrollment") {
      //props.setActiveContent({...props.activeContent, route:'anc-enrollment', id:row.id, actionType:action})
      history.push({
        pathname: "/update-patient",
        state: {
          id: row.recordId,
          patientObj: props.patientObj,
          actionType: action,
        },
      });
    } else if (row.path === "anc-delivery") {
      props.setActiveContent({
        ...props.activeContent,
        route: "labour-delivery",
        id: row.recordId,
        actionType: action,
      });
    } else if (row.path === "pmtct-enrollment") {
      props.setActiveContent({
        ...props.activeContent,
        route: "anc-pnc",
        id: row.recordId,
        activeTab: "history",
        actionType: action,
      });
    } else if (row.path === "anc-mother-visit") {
      props.setActiveContent({
        ...props.activeContent,
        route: "consultation",
        id: row.recordId,
        activeTab: "home",
        actionType: action,
      });
    } else if (row.path === "pmtct_infant_visit") {
      props.setActiveContent({
        ...props.activeContent,
        route: "infant-visit",
        id: row.recordId,
        activeTab: "child",
        actionType: action,
      });
    } else if (row.path === "pmtct_infant_information") {
      props.setActiveContent({
        ...props.activeContent,
        route: "add-infant",
        id: row.recordId,
        activeTab: "home",
        actionType: action,
      });
    } else if (row.path === "pmtct-family-planning") {
      props.setActiveContent({
        ...props.activeContent,
        route: "family-planning",
        id: row.recordId,
        activeTab: "home",
        actionType: action,
      });
    } else if (row.path === "pmtct-hts") {
      props.setActiveContent({
        ...props.activeContent,
        route: "pmtct-hts",
        id: row.recordId,
        activeTab: "home",
        actionType: action,
      });

      if (props.setPmtctHtsRetestingType) {
        const isRetesting = (row?.testingType && row.testingType.toUpperCase() === "RETESTING")
          || row?.activityName?.toLowerCase() === "retesting";
        props.setPmtctHtsRetestingType(isRetesting ? "retesting" : "pmtct-hts")
      }
    } else {
    }
  };
  const LoadDeletePage = (row) => {
    if (row.path === "anc-enrollment") {
      setSaving(true);
      //props.setActiveContent({...props.activeContent, route:'mental-health-view', id:row.id})
      axios
        .delete(`${baseUrl}pmtct/anc/delete/anc/${row.recordId}`, {
          headers: { Authorization: `Bearer ${token}` },
        })
        .then((response) => {
          toast.success("Record Deleted Successfully");
          PatientHistory();
          toggle();
          setSaving(false);
        })
        .catch((error) => {
          setSaving(false);
          if (error.response && error.response.data) {
            let errorMessage =
              error.response.data.apierror &&
              error.response.data.apierror.message !== ""
                ? error.response.data.apierror.message
                : "Something went wrong, please try again";
            toast.error(errorMessage);
          } else {
            toast.error("Something went wrong. Please try again...");
          }
        });
    } else if (row.path === "pmtct-enrollment") {
      setSaving(true);
      //props.setActiveContent({...props.activeContent, route:'art-commencement-view', id:row.id})
      axios
        .delete(`${baseUrl}pmtct/anc/delete/pmtct/${row.recordId}`, {
          headers: { Authorization: `Bearer ${token}` },
        })
        .then((response) => {
          toast.success("Record Deleted Successfully");
          PatientHistory();
          toggle();
          setSaving(false);
        })
        .catch((error) => {
          setSaving(false);
          if (error.response && error.response.data) {
            let errorMessage =
              error.response.data.apierror &&
              error.response.data.apierror.message !== ""
                ? error.response.data.apierror.message
                : "Something went wrong, please try again";
            toast.error(errorMessage);
          } else {
            toast.error("Something went wrong. Please try again...");
          }
        });
    } else if (row.path === "anc-delivery") {
      setSaving(true);
      //props.setActiveContent({...props.activeContent, route:'art-commencement-view', id:row.id})
      axios
        .delete(`${baseUrl}pmtct/anc/delete/delivery/${row.recordId}`, {
          headers: { Authorization: `Bearer ${token}` },
        })
        .then((response) => {
          toast.success("Record Deleted Successfully");
          PatientHistory();
          toggle();
          setSaving(false);
        })
        .catch((error) => {
          setSaving(false);
          if (error.response && error.response.data) {
            let errorMessage =
              error.response.data.apierror &&
              error.response.data.apierror.message !== ""
                ? error.response.data.apierror.message
                : "Something went wrong, please try again";
            toast.error(errorMessage);
          } else {
            toast.error("Something went wrong. Please try again...");
          }
        });
    } else if (row.path === "anc-mother-visit") {
      setSaving(true);
      //props.setActiveContent({...props.activeContent, route:'art-commencement-view', id:row.id})
      axios
        .delete(`${baseUrl}pmtct/anc/delete/mothervisit/${row.recordId}`, {
          headers: { Authorization: `Bearer ${token}` },
        })
        .then((response) => {
          toast.success("Record Deleted Successfully");
          PatientHistory();
          toggle();
          setSaving(false);
        })
        .catch((error) => {
          setSaving(false);
          if (error.response && error.response.data) {
            let errorMessage =
              error.response.data.apierror &&
              error.response.data.apierror.message !== ""
                ? error.response.data.apierror.message
                : "Something went wrong, please try again";
            toast.error(errorMessage);
          } else {
            toast.error("Something went wrong. Please try again...");
          }
        });
    } else if (row.path === "pmtct_infant_visit") {
      setSaving(true);
      //props.setActiveContent({...props.activeContent, route:'art-commencement-view', id:row.id})
      axios
        .delete(`${baseUrl}pmtct/anc/delete/infantvisit/${row.recordId}`, {
          headers: { Authorization: `Bearer ${token}` },
        })
        .then((response) => {
          toast.success("Record Deleted Successfully");
          PatientHistory();
          toggle();
          setSaving(false);
        })
        .catch((error) => {
          setSaving(false);
          if (error.response && error.response.data) {
            let errorMessage =
              error.response.data.apierror &&
              error.response.data.apierror.message !== ""
                ? error.response.data.apierror.message
                : "Something went wrong, please try again";
            toast.error(errorMessage);
          } else {
            toast.error("Something went wrong. Please try again...");
          }
        });
    } else if (row.path === "pmtct-family-planning") {
      setSaving(true);
      axios
        .delete(`${baseUrl}pmtct/anc/delete/family-planning-visit/${row.recordId}`, {
          headers: { Authorization: `Bearer ${token}` },
        })
        .then((response) => {
          toast.success("Record Deleted Successfully");
          PatientHistory();
          toggle();
          setSaving(false);
        })
        .catch((error) => {
          setSaving(false);
          if (error.response && error.response.data) {
            let errorMessage =
              error.response.data.apierror &&
              error.response.data.apierror.message !== ""
                ? error.response.data.apierror.message
                : "Something went wrong, please try again";
            toast.error(errorMessage);
          } else {
            toast.error("Something went wrong. Please try again...");
          }
        });
    } else if (row.path === "pmtct_infant_information") {
      setSaving(true);
      //props.setActiveContent({...props.activeContent, route:'art-commencement-view', id:row.id})
      axios
        .delete(`${baseUrl}pmtct/anc/delete/infantinfo/${row.recordId}`, {
          headers: { Authorization: `Bearer ${token}` },
        })
        .then((response) => {
          toast.success("Record Deleted Successfully");
          PatientHistory();
          toggle();
          setSaving(false);
        })
        .catch((error) => {
          setSaving(false);
          if (error.response && error.response.data) {
            let errorMessage =
              error.response.data.apierror &&
              error.response.data.apierror.message !== ""
                ? error.response.data.apierror.message
                : "Something went wrong, please try again";
            toast.error(errorMessage);
          } else {
            toast.error("Something went wrong. Please try again...");
          }
        });
    } else if (row.path === "pmtct-hts") {
      setSaving(true);
      // Numeric recordId → post-migration hts_encounter record — delete goes straight to
      // HTS-Module's own DELETE /api/v1/hts-encounter/{id} instead of PMTCT's retired
      // delete/pmtct-hts/{id}. Non-numeric (legacy UUID) ids still use PMTCT's own endpoint,
      // which HTS's endpoints have no way to reference at all.
      const isLegacyRecordId = row.recordId != null && !/^\d+$/.test(String(row.recordId));
      const deleteUrl = isLegacyRecordId
        ? `${baseUrl}pmtct/anc/delete/pmtct-hts/${row.recordId}`
        : `${baseUrl}hts-encounter/${row.recordId}`;
      axios
        .delete(deleteUrl, {
          headers: { Authorization: `Bearer ${token}` },
        })
        .then((response) => {
          toast.success("Record Deleted Successfully");
          PatientHistory();
          toggle();
          setSaving(false);
          // Notify parent so PatientCard re-fetches HIV status after HTS deletion
          if (props.setActiveContent) {
            props.setActiveContent((prev) => ({ ...prev, actionType: "hts-deleted" }));
          }
        })
        .catch((error) => {
          setSaving(false);
          const errorMessage =
            error.response?.data?.message ||
            (error.response?.data?.apierror && error.response.data.apierror.message !== ""
              ? error.response.data.apierror.message
              : null) ||
            "Something went wrong, please try again";
          toast.error(errorMessage);
        });
    } else {
    }
  };
  const LoadModal = (row) => {
    toggle();
    setRecord(row);
  };

  return (
    <div>
      <br />

      <MaterialTable
        icons={tableIcons}
        title="Patient History "
        columns={[
          { title: "Description", field: "name" },
          {
            title: "Encounter Date",
            field: "date",
          },
          // { title: "Status", field: "status", filtering: false },
          { title: "Actions", field: "actions", filtering: false },
        ]}
        isLoading={loading}
        data={
          recentActivities &&
          recentActivities.map((row) => ({
            name: displayActivityName(row.activityName, row),
            date: row.activityDate,
            actions: !notToBeUpdated.includes(row.path) ? (
              <Dropdown className="dropdown">
                <Dropdown.Toggle
                  variant=" light"
                  className="i-false p-0 btn-info sharp"
                >
                  <svg
                    width="18px"
                    height="18px"
                    viewBox="0 0 24 24"
                    version="1.1"
                  >
                    <g
                      stroke="none"
                      strokeWidth="1"
                      fill="none"
                      fillRule="evenodd"
                    >
                      <rect
                        x="0"
                        y="0"
                        width="24"
                        height="24"
                      />
                      <circle
                        fill="#000000"
                        cx="5"
                        cy="12"
                        r="2"
                      />
                      <circle
                        fill="#000000"
                        cx="12"
                        cy="12"
                        r="2"
                      />
                      <circle
                        fill="#000000"
                        cx="19"
                        cy="12"
                        r="2"
                      />
                    </g>
                  </svg>
                </Dropdown.Toggle>
                <Dropdown.Menu className="dropdown-menu">
                  {row.viewable && (
                    <Dropdown.Item
                      className="dropdown-item"
                      onClick={() => LoadViewPage(row, "view")}
                    >
                      View
                    </Dropdown.Item>
                  )}
                  {row.viewable && (
                    <Dropdown.Item
                      className="dropdown-item"
                      onClick={() => LoadViewPage(row, "update")}
                    >
                      Update
                    </Dropdown.Item>
                  )}
                  <Dropdown.Item
                    className="dropdown-item"
                    onClick={() => LoadModal(row, "delete")}
                  >
                    Delete
                  </Dropdown.Item>
                </Dropdown.Menu>
              </Dropdown>
            ) : (
              ""
            ),
          }))
        }
        options={{
          headerStyle: {
            backgroundColor: "#014d88",
            color: "#fff",
          },
          searchFieldStyle: {
            width: "200%",
            margingLeft: "250px",
          },
          filtering: false,
          exportButton: false,
          searchFieldAlignment: "left",
          pageSizeOptions: [10, 20, 100],
          pageSize: 10,
          debounceInterval: 400,
        }}
      />
      <Modal
        show={open}
        toggle={toggle}
        className="fade"
        size="md"
        aria-labelledby="contained-modal-title-vcenter"
        centered
        backdrop="static"
      >
        <Modal.Header>
          <Modal.Title id="contained-modal-title-vcenter">
            Notification!
          </Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <h4>
            Are you Sure you want to delete{" "}
            <b>{record && record.activityName}</b>
          </h4>
        </Modal.Body>
        <Modal.Footer>
          <Button
            onClick={() => LoadDeletePage(record)}
            style={{ backgroundColor: "red", color: "#fff" }}
            disabled={saving}
          >
            {saving === false ? "Yes" : "Deleting..."}
          </Button>
          <Button
            onClick={toggle}
            style={{ backgroundColor: "#014d88", color: "#fff" }}
            disabled={saving}
          >
            No
          </Button>
        </Modal.Footer>
      </Modal>
    </div>
  );
};

export default PatientnHistory;
